dtsPropsFor.PanelTitle:
title: string;
tone: 'primary' | 'secondary' | 'tertiary' | 'neutral';
detail?: string;
endContent?: React.ReactNode;

dtsPropsFor.StatRibbon:
label: string;
value: string;
detail: string;
tone: 'primary' | 'secondary' | 'tertiary' | 'neutral';
/** Narrow padding + smaller value font variant. */
dense?: boolean;
className?: string;

dtsPropsFor.MetricTile:
label: string;
value: string;
tone: 'primary' | 'secondary' | 'tertiary' | 'neutral';
note?: string;
/** Narrow padding + smaller font variant. */
compact?: boolean;
className?: string;

dtsPropsFor.TrackStrip:
/** Total track length in meters — the bar's coordinate space. */
trackLength: number;
/** Sector boundaries as lapDistance in meters: [end of S1, end of S2]. S3 ends at trackLength. */
sectorSplits: [number, number];
/** Corner markers drawn above the bar as T{number} labels + ticks. distance = apex lapDistance (m). */
corners?: { number: number; distance: number }[];
/** Driver dots. color = team color (falls back to the tone accent); focused adds a ring + code label; inPit dims the dot. */
drivers?: { code: string; distance: number; color?: string; focused?: boolean; inPit?: boolean }[];
/** Accent for the focused ring and start/finish marker. Default 'primary'. */
tone?: 'primary' | 'secondary' | 'tertiary' | 'neutral';
className?: string;
